import { categories, questions, isComplete, scores, priorities, level, currentMonth, monthName, seedRecords, validRecord } from './domain.mjs';

const paths = {
  leaf: '<path d="M5 20C3 8 12 4 21 3c0 11-5 17-16 17Z"/><path d="m5 20 11-11"/>',
  dashboard: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  clipboard: '<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="m9 13 2 2 4-4"/>',
  chart: '<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V4"/>',
  target: '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  history: '<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',
  bolt: '<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',
  drop: '<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/><path d="M9 15a3 3 0 0 0 3 3"/>',
  recycle: '<path d="m9 5 3-3 5 8m-4-1 4 1 1-4M20 12l2 4-4 5H9m3-3-3 3 3 3M6 19H2l-1-5 5-8m-1 5 1-5 5 1" transform="translate(1 0) scale(.9)"/>',
  paper: '<path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v6h5M8 13h8m-8 4h6"/>',
  bike: '<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-9 5 9H5m10 0 4-12h-4M8 8h5"/>',
  office: '<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h1m4 0h1M9 11h1m4 0h1M9 15h1m4 0h1m-4 6v-3h2v3"/>',
  arrow: '<path d="M5 12h14m-5-5 5 5-5 5"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2"/>',
  trend: '<path d="m3 17 6-6 4 4 8-10m-6 0h6v6"/>',
  info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/>',
  chevron: '<path d="m9 5 7 7-7 7"/>'
};
const icon = (name, cls = '') => `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.leaf}</svg>`;
const $ = s => document.querySelector(s);
const STORE = 'greener-office-v1', DRAFT = 'greener-draft-v1';
let storageWarning = false;
let records = seedRecords();
try { const raw = localStorage.getItem(STORE); if (raw) { const data = JSON.parse(raw); if (!Array.isArray(data) || !data.every(validRecord) || new Set(data.map(r => r.month)).size !== data.length) throw new Error('Data tidak valid'); records = data; } else localStorage.setItem(STORE, JSON.stringify(records)); } catch { storageWarning = true; }
let draft = {}, showErrors = false;
try { const raw = JSON.parse(localStorage.getItem(DRAFT) || 'null'); if (raw?.month === currentMonth()) draft = Object.fromEntries(questions.filter(q => [0,50,100].includes(raw.answers?.[q.id])).map(q => [q.id, raw.answers[q.id]])); else draft = { ...records.find(r => r.month === currentMonth())?.answers }; } catch { draft = { ...records.find(r => r.month === currentMonth())?.answers }; }
let toastTimer;
function toast(text) { $('#toast').textContent = text; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 4200); }
function write(key, data) { try { localStorage.setItem(key, JSON.stringify(data)); return true; } catch { storageWarning = true; toast('Penyimpanan browser tidak tersedia. Perubahan hanya bertahan selama halaman ini terbuka.'); return false; } }
const ordered = () => [...records].sort((a,b) => a.month.localeCompare(b.month));
const latest = () => ordered().at(-1);
const badge = (n) => `<span class="badge ${n >= 70 ? 'good' : n < 40 ? 'low' : ''}"><i></i>${level(n)}</span>`;
const button = (text, href, type = 'primary') => `<a class="btn ${type}" href="#${href}">${text}${icon('arrow')}</a>`;
const monthChip = month => `<span class="month-chip">${icon('calendar')}${monthName(month)}</span>`;
function heading(eyebrow, title, subtitle, action = '') { return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function scoreRing(score, size = '') { return `<div class="score-ring ${size}" style="--score:${score}" role="img" aria-label="Skor ${Math.round(score)} dari 100"><div><strong>${Math.round(score)}</strong><span>dari 100 poin</span></div></div>`; }
function catBars(record) { return scores(record.answers).categories.map(c => `<div class="category-bar"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><span class="category-name">${c.name}</span><div class="bar-track"><i style="width:${c.score}%;--cat:${c.color}"></i></div><strong>${Math.round(c.score)}<small>/100</small></strong></div>`).join(''); }
function plantArt() { return `<svg class="plant-art" viewBox="0 0 240 240" fill="none" aria-hidden="true"><circle cx="130" cy="110" r="92" fill="#e7eddb"/><circle cx="42" cy="58" r="4" fill="#a6b48b"/><circle cx="208" cy="145" r="5" fill="#c2cba7"/><path d="M125 177V79m0 59-36-33m36 14 32-32" stroke="#668260" stroke-width="3" stroke-linecap="round"/><path d="M124 108c-33 0-54-24-46-46 29-2 49 19 46 46Z" fill="#8aa475"/><path d="M126 135c31 1 57-20 52-44-27-5-50 15-52 44Z" fill="#698c68"/><path d="M126 85c-10-30 0-54 22-57 13 25 1 48-22 57Z" fill="#416b4a"/><path d="M121 156c-29 0-49-17-45-36 25-4 45 12 45 36Z" fill="#a5b68c"/><path d="m95 173 9 43h42l9-43H95Z" fill="#d6c3a2"/><path d="M91 171h68v10H91z" fill="#e6d5b8"/><path d="M88 217h75" stroke="#aab591" stroke-width="2" stroke-linecap="round"/><path d="m38 130 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1 3-7Z" stroke="#b1bc9b" stroke-width="1.5"/></svg>`; }
function trendChart() {
  const data = ordered().slice(-6), values = data.map(r => scores(r.answers).total);
  const points = values.map((v,i) => `${50 + i * (450 / Math.max(1, data.length - 1))},${150 - v * 1.15}`);
  return `<div class="trend-chart"><svg viewBox="0 0 550 190" role="img" aria-label="Perkembangan skor: ${data.map((r,i) => `${monthName(r.month)} ${Math.round(values[i])}`).join(', ')}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#dce9d9" stop-opacity=".9"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs>${[0,50,100].map(v=>`<text x="4" y="${155-v*1.15}" class="chart-label">${v}</text><path d="M35 ${150-v*1.15}H520" stroke="#eef0ea" stroke-dasharray="4 5"/>`).join('')}<path d="M${points.join(' L')}L${50+(data.length-1)*(450/Math.max(1,data.length-1))} 150H50Z" fill="url(#chart-fill)"/><path d="M${points.join(' L')}" stroke="#4b7957" stroke-width="2.5" fill="none"/>${points.map((point,i) => {const [x,y]=point.split(',');return `<circle cx="${x}" cy="${y}" r="4.5" fill="#4b7957" stroke="#fff" stroke-width="2"/><text x="${x}" y="${Number(y)-13}" text-anchor="middle" class="chart-value">${Math.round(values[i])}</text><text x="${x}" y="179" text-anchor="middle" class="chart-label">${monthName(data[i].month,true)}</text>`;}).join('')}</svg></div>`;
}
function tasksPreview(record) { const tasks = priorities(record.answers); return tasks.length ? tasks.map((q,i) => {const c=categories.find(c=>c.id===q.category);return `<a class="preview-task" href="#perbaikan/${record.month}"><span class="task-number">0${i+1}</span><div><strong>${q.action}</strong><span>${c.name} <span class="dot-separator">·</span> ${record.completed.includes(q.id) ? 'Selesai' : 'Belum selesai'}</span></div>${icon('chevron')}</a>`;}).join('') : `<div class="empty-inline">${icon('check')} Semua praktik sudah dijalankan. Pertahankan kebiasaan baik ini.</div>`; }
function dashboard() {
  const r=latest(); if(!r) return heading('SELAMAT DATANG DI GREENER', 'Kantor lebih hijau dimulai di sini.', 'Isi penilaian pertama untuk melihat skor dan prioritas perbaikan.', button('Mulai penilaian','penilaian'));
  const s=scores(r.answers), prev=ordered().at(-2), diff=prev ? s.total-scores(prev.answers).total : 0, tasks=priorities(r.answers), done=tasks.filter(q=>r.completed.includes(q.id)).length, hasCurrent=records.some(r=>r.month===currentMonth());
  return `${heading('SETIAP LANGKAH BERARTI', 'Kantor lebih hijau, mulai dari kita.', 'Kenali kebiasaan hari ini. Bangun perubahan untuk hari esok.', button(hasCurrent?'Perbarui penilaian':'Mulai penilaian','penilaian'))}
  <div class="overview-grid"><section class="score-card"><div class="card-top"><span class="eyebrow">SKOR GREEN OFFICE</span>${monthChip(r.month)}</div><div class="score-card-body">${scoreRing(s.total)}<div class="score-copy">${badge(s.total)}<h2>${s.total>=90?'Kebiasaan baik mulai terjaga.':s.total>=40?'Sudah di jalur yang baik.':'Langkah pertama dimulai di sini.'}</h2><p>${s.total===100?'Semua praktik sudah dijalankan.<br>Pertahankan kebiasaan baik ini.':'Masih ada ruang untuk tumbuh.<br>Mulai dari satu kebiasaan kecil.'}</p><a class="text-link" href="#hasil/${r.month}">Lihat detail penilaian ${icon('arrow')}</a></div></div><div class="score-card-bottom"><span>${icon('trend')} <strong>${diff>=0?'+':''}${Math.round(diff)} poin</strong> ${prev?'dari bulan sebelumnya':'penilaian awal'}</span><span>${r.demo?'Data contoh':'Penilaian tersimpan'}</span></div></section><section class="welcome-card"><div class="eyebrow">SMALL STEPS. BIG DIFFERENCE.</div><h2>Ruang kerja baik.<br>Bumi ikut baik.</h2><p>Lima aspek sederhana untuk<br>kantor yang lebih berkelanjutan.</p>${plantArt()}<span class="welcome-label">${icon('leaf')} Tumbuh lebih baik, bersama.</span></section></div>
  <div class="metrics"><div class="metric">${icon('clipboard')}<div><span>Penilaian tersimpan</span><strong>${records.length}<small>bulan perjalanan</small></strong></div></div><div class="metric">${icon('leaf')}<div><span>Kategori dinilai</span><strong>5<small>aspek green office</small></strong></div></div><div class="metric">${icon('target')}<div><span>Tindakan diselesaikan</span><strong>${done}<small>dari ${tasks.length} prioritas terakhir</small></strong></div></div></div>
  <div class="details-grid"><section class="panel"><div class="section-top"><div><h2>Skor per kategori</h2><p>Kenali kekuatan dan ruang perbaikan.</p></div><span class="subtle">${monthName(r.month,true)}</span></div><div class="category-bars">${catBars(r)}</div><a class="panel-link" href="#hasil/${r.month}">Jelajahi hasil penilaian ${icon('arrow')}</a></section><section class="panel"><div class="section-top"><div><h2>Perjalanan hijau kita</h2><p>Setiap kemajuan layak dirayakan.</p></div><span class="badge neutral">${records.length} bulan</span></div>${trendChart()}<a class="panel-link" href="#riwayat">Lihat seluruh riwayat ${icon('arrow')}</a></section></div>
  <section class="panel priorities-panel"><div class="section-top"><div><h2>Langkah berikutnya</h2><p>Perubahan paling berarti dimulai dari sini.</p></div><a class="text-link" href="#perbaikan/${r.month}">Semua tindakan ${icon('arrow')}</a></div><div class="preview-tasks">${tasksPreview(r)}</div></section>
  <div class="local-note">${icon('info')} Data tersimpan di browser ini. Gunakan data contoh untuk menjelajahi prototype.</div>`;
}
function assessment() {
  const count=questions.filter(q=>draft[q.id]!==undefined).length;
  return `${heading('PENILAIAN BULANAN','Seberapa hijau kantor kita?', 'Jawab sesuai kebiasaan yang benar-benar dijalankan di kantor.',monthChip(currentMonth()))}
  <div class="assessment-layout"><div><div class="form-guide">${icon('info')}<p><strong>Tidak perlu sempurna untuk memulai.</strong> Pilih Belum, Sebagian, atau Sudah untuk setiap praktik. Semua 15 pertanyaan wajib dijawab.</p></div><form id="assessment-form" novalidate>${categories.map((c,ci)=>`<section class="panel question-section"><div class="question-section-header"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><div><span class="eyebrow">ASPEK 0${ci+1}</span><h2>${c.name}</h2><p>${c.description}</p></div></div>${questions.filter(q=>q.category===c.id).map((q,i)=>`<fieldset id="field-${q.id}" class="question ${showErrors&&draft[q.id]===undefined?'invalid':''}"><legend><span class="q-number">${String(ci*3+i+1).padStart(2,'0')}</span>${q.text}</legend><p id="hint-${q.id}">${q.hint}</p><div class="answers">${[[0,'Belum'],[50,'Sebagian'],[100,'Sudah']].map(([value,label])=>`<label class="answer"><input type="radio" name="${q.id}" value="${value}" ${draft[q.id]===value?'checked':''} aria-describedby="hint-${q.id}" required><span><i></i>${label}<small>${value} poin</small></span></label>`).join('')}</div><span class="field-error" ${showErrors&&draft[q.id]===undefined?'':'hidden'}>Pilih satu jawaban untuk praktik ini.</span></fieldset>`).join('')}</section>`).join('')}<div class="form-submit"><span id="form-error" role="alert">${showErrors&&count<15?'Lengkapi semua jawaban sebelum melihat hasil.':''}</span><button class="btn primary" type="submit">Simpan & lihat hasil ${icon('arrow')}</button></div></form></div><aside class="assessment-aside"><section class="panel"><div class="eyebrow">LANGKAH KECIL ANDA</div><h2>Progress penilaian</h2><div class="progress-number"><strong id="answered-count">${count}</strong><span>/ 15 terjawab</span></div><div class="bar-track"><i id="form-progress" style="width:${count/15*100}%;--cat:var(--green)"></i></div><p>Draf otomatis tersimpan di browser ini.</p><div class="aside-divider"></div><h3>Bagaimana skornya dihitung?</h3><p>Setiap kategori memiliki bobot yang sama. Skor akhir adalah rata-rata lima kategori.</p><div class="scoring-key"><span>Belum <strong>0</strong></span><span>Sebagian <strong>50</strong></span><span>Sudah <strong>100</strong></span></div><p class="fine-print">Ini adalah simulasi edukatif, bukan penilaian sertifikasi lingkungan.</p></section></aside></div>`;
}
function result(r) {
  const s=scores(r.answers), previous=ordered().filter(x=>x.month<r.month).at(-1), diff=previous?s.total-scores(previous.answers).total:null;
  return `${heading('HASIL PENILAIAN','Setiap langkah punya arti.', 'Inilah gambaran praktik green office kantor Anda.',monthChip(r.month))}<div class="result-summary panel">${scoreRing(s.total,'large')}<div>${badge(s.total)}<h2>${s.total>=90?'Kebiasaan baik sudah menjadi budaya.':s.total>=70?'Langkah baik untuk kantor yang lebih hijau.':'Ada langkah sederhana yang bisa kita mulai.'}</h2><p>Skor ini merangkum 15 praktik di lima kategori. Gunakan hasilnya untuk menentukan perubahan yang paling masuk akal bagi kantor.</p>${diff!==null?`<div class="comparison">${icon('trend')} ${diff>=0?'+':''}${Math.round(diff)} poin dibanding ${monthName(previous.month)}</div>`:''}<span class="subtle">${r.demo?'Penilaian contoh · ':''}Skor simulasi, bukan sertifikasi</span></div></div><div class="section-heading"><div><h2>Lima aspek, satu tujuan.</h2><p>Skor kategori adalah rata-rata tiga praktik di dalamnya.</p></div></div><div class="result-categories">${s.categories.map(c=>`<section class="panel result-category"><div class="result-category-title"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><h2>${c.name}</h2><strong>${Math.round(c.score)}<small>/100</small></strong></div><div class="bar-track"><i style="width:${c.score}%;--cat:${c.color}"></i></div><ul>${questions.filter(q=>q.category===c.id).map(q=>`<li><span>${q.text}</span><span class="answer-status v${r.answers[q.id]}">${{0:'Belum',50:'Sebagian',100:'Sudah'}[r.answers[q.id]]}</span></li>`).join('')}</ul></section>`).join('')}</div><div class="next-banner"><div>${icon('target')}<div><h2>Ubah hasil menjadi langkah nyata.</h2><p>Mulai dari tiga prioritas yang sesuai dengan jawaban Anda.</p></div></div>${button('Lihat rencana perbaikan',`perbaikan/${r.month}`)}</div>${r.month===currentMonth()?`<div class="center-link"><a class="text-link" href="#penilaian">Edit penilaian bulan ini ${icon('arrow')}</a></div>`:''}`;
}
function improvements(r) {
  const tasks=priorities(r.answers), done=tasks.filter(q=>r.completed.includes(q.id)).length;
  return `${heading('RENCANA PERBAIKAN','Dari niat baik, jadi kebiasaan.', 'Fokus pada langkah yang sederhana dan bisa dimulai hari ini.',monthChip(r.month))}<div class="action-summary"><div class="action-summary-icon">${icon('target')}</div><div><h2>${done} dari ${tasks.length} tindakan selesai</h2><p>Prioritas dipilih dari praktik dengan skor terendah pada penilaian ini.</p></div><div class="action-progress"><div class="bar-track"><i style="width:${tasks.length?done/tasks.length*100:100}%;--cat:var(--green)"></i></div><span>${tasks.length?Math.round(done/tasks.length*100):100}% selesai</span></div></div><div class="action-list">${tasks.length?tasks.map((q,i)=>{const c=categories.find(c=>c.id===q.category),checked=r.completed.includes(q.id);return `<article class="panel action-card ${checked?'completed':''}"><div class="action-card-top"><span class="category-tag" style="--cat:${c.color}">${icon(c.icon)}${c.name}</span><span class="subtle">PRIORITAS 0${i+1}</span></div><h2>${q.action}</h2><p>${q.advice}</p><div class="action-context">Dari penilaian Anda: <strong>${r.answers[q.id]===0?'Belum':'Sebagian'}</strong><span>${q.text}</span></div><label class="task-check"><input type="checkbox" data-task="${q.id}" data-month="${r.month}" ${checked?'checked':''}><span>${checked?'Tindakan sudah dilakukan':'Tandai jika sudah dilakukan'}</span></label></article>`;}).join(''):`<section class="panel empty-state">${icon('leaf')}<h2>Semua praktik sudah dijalankan.</h2><p>Pertahankan kebiasaan baik dan tinjau lagi pada penilaian bulan berikutnya.</p></section>`}</div><div class="form-guide action-guide">${icon('info')}<p><strong>Tindakan selesai tidak langsung mengubah skor.</strong> Catat kebiasaan terbaru saat penilaian bulan berikutnya untuk melihat perkembangannya.</p></div><div class="bottom-links"><a class="text-link" href="#hasil/${r.month}">Kembali ke hasil ${icon('arrow')}</a>${button('Ke dashboard','dashboard','secondary')}</div>`;
}
function history() {
  const data=ordered().reverse(), first=ordered()[0], last=latest(), growth=last&&first?scores(last.answers).total-scores(first.answers).total:0;
  return `${heading('RIWAYAT PENILAIAN','Lihat seberapa jauh kita tumbuh.', 'Catatan kecil dari perjalanan kantor yang lebih hijau.',button(records.some(r=>r.month===currentMonth())?'Perbarui penilaian':'Mulai penilaian','penilaian'))}<div class="history-overview"><section class="panel history-stat"><span class="eyebrow">BULAN TERCATAT</span><strong>${data.length}<small>penilaian bulanan</small></strong></section><section class="panel history-stat"><span class="eyebrow">PERUBAHAN SEJAK AWAL</span><strong>${growth>=0?'+':''}${Math.round(growth)}<small>poin perjalanan</small></strong></section></div><section class="panel history-panel"><div class="section-top"><div><h2>Semua penilaian</h2><p>Satu bulan, satu kesempatan untuk lebih baik.</p></div><span class="badge neutral">${data.length} catatan</span></div><div class="table-wrap"><table><thead><tr><th>Periode penilaian</th><th>Skor total</th><th>Perubahan</th><th>Status</th><th><span class="sr-only">Aksi</span></th></tr></thead><tbody>${data.map(r=>{const s=scores(r.answers).total,prev=ordered().filter(x=>x.month<r.month).at(-1),diff=prev?s-scores(prev.answers).total:null;return `<tr><td><span class="table-period">${icon('calendar')}<span><strong>${monthName(r.month)}</strong><small>${r.demo?'Data contoh':'Penilaian kantor'}</small></span></span></td><td><strong class="table-score">${Math.round(s)}</strong><small> / 100</small></td><td><span class="${diff!==null&&diff>=0?'positive':''}">${diff===null?'—':`${diff>=0?'+':''}${Math.round(diff)} poin`}</span></td><td>${badge(s)}</td><td><a class="text-link" href="#hasil/${r.month}">Lihat hasil ${icon('arrow')}</a></td></tr>`;}).join('')}</tbody></table></div></section><div class="local-note">${icon('info')} Penilaian bulan berjalan dapat diedit. Bulan sebelumnya disimpan sebagai riwayat.</div>`;
}
const navItems=[['dashboard','dashboard','Dashboard'],['penilaian','clipboard','Penilaian'],['hasil','chart','Hasil penilaian'],['perbaikan','target','Rencana perbaikan'],['riwayat','history','Riwayat']];
function render() {
  const [page='dashboard',month] = (location.hash.slice(1)||'dashboard').split('/');
  const known=navItems.find(x=>x[0]===page), active=known?.[0]||'dashboard';
  $('#navigation').innerHTML=navItems.map(([route,i,label])=>`<a href="#${route}" ${route===active?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${route==='penilaian'?'<span class="nav-small-dot"></span>':''}</a>`).join('');
  $('#breadcrumb').textContent=known?.[2]||'Dashboard';
  document.title=`${known?.[2]||'Dashboard'} — Greener`;
  const record = month ? records.find(r=>r.month===month) : latest();
  let html;
  if(active==='penilaian') html=assessment();
  else if(active==='hasil'||active==='perbaikan') html=record?(active==='hasil'?result(record):improvements(record)):`${heading('BELUM ADA HASIL','Mulai perjalanan hijau Anda.',month?'Penilaian untuk periode ini tidak ditemukan.':'Isi penilaian untuk mendapatkan skor dan saran perbaikan.',button('Mulai penilaian','penilaian'))}`;
  else html=active==='riwayat'?history():dashboard();
  $('#main').innerHTML=(storageWarning?'<div class="storage-warning" role="alert">Penyimpanan browser tidak tersedia atau data sebelumnya tidak dapat dibaca. Periksa pengaturan browser agar perubahan tetap tersimpan.</div>':'')+html;
}
$('#brand-icon').innerHTML=icon('leaf');$('#office-icon').innerHTML=icon('office');$('#note-icon').innerHTML=icon('leaf');
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
document.addEventListener('change',e=>{
  const input=e.target;
  if(input.matches('#assessment-form input[type="radio"]')) { draft[input.name]=Number(input.value);write(DRAFT,{month:currentMonth(),answers:draft});const count=questions.filter(q=>draft[q.id]!==undefined).length;$('#answered-count').textContent=count;$('#form-progress').style.width=`${count/15*100}%`;input.closest('fieldset').classList.remove('invalid');input.closest('fieldset').querySelector('.field-error').hidden=true;if(count===15)$('#form-error').textContent=''; }
  if(input.matches('[data-task]')) { const record=records.find(r=>r.month===input.dataset.month);if(!record)return;record.completed=record.completed.filter(id=>id!==input.dataset.task);if(input.checked)record.completed.push(input.dataset.task);const success=write(STORE,records);const checked=input.checked;render();const replacement=document.querySelector(`[data-task="${input.dataset.task}"]`);replacement?.focus({preventScroll:true});if(success)toast(checked?'Satu langkah baik sudah dilakukan. Progres tersimpan.':'Status tindakan diperbarui.'); }
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='assessment-form')return;e.preventDefault();
  if(!isComplete(draft)){showErrors=true;render();const missing=questions.find(q=>draft[q.id]===undefined);$(`#field-${missing.id}`).scrollIntoView({behavior:'smooth',block:'center'});$(`#field-${missing.id} input`).focus({preventScroll:true});return;}
  const month=currentMonth(), old=records.find(r=>r.month===month), record={month,answers:{...draft},completed:(old?.completed||[]).filter(id=>old.answers[id]===draft[id]),demo:false};
  records=records.filter(r=>r.month!==month);records.push(record);const saved=write(STORE,records);write(DRAFT,{month,answers:draft});showErrors=false;location.hash=`hasil/${month}`;if(saved)toast('Penilaian tersimpan. Langkah hijau berikutnya menanti.');
});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
for(const id of ['#reset-demo','#reset-demo-mobile'])$(id).addEventListener('click',()=>$('#reset-dialog').showModal());
$('#reset-dialog').addEventListener('close',()=>{if($('#reset-dialog').returnValue!=='reset')return;records=seedRecords();draft={};showErrors=false;const saved=write(STORE,records);write(DRAFT,{month:currentMonth(),answers:{}});if(location.hash==='#dashboard')render();else location.hash='dashboard';if(saved)toast('Data contoh dipulihkan. Siap menjelajahi lagi.');});
render();
